"""v73 — put back what v71/v72 changed without being asked.
Player Grid: exactly the pre-v71 grid again (four tables across, the original columns and widths, no RZ / L5 / SCORE columns,
no $ chips). The rank subscript stays where a table has room for it and is dropped where it would cut a figure.
Category Grid: the original five-across layout and column widths again; the 'scored marks live' line is gone.
Kept from v72: no check-off boxes, and the scored marks refreshing live from ESPN. Rerunnable."""
import os, sys
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
P = 'scripts/dashboard_template.html'
s = open(P, encoding='utf-8').read()
if '/* v73 */' in s:
    print('v73 already applied'); sys.exit(0)
def rep(old, new, n=1):
    global s
    assert s.count(old) == n, (s.count(old), old[:110])
    s = s.replace(old, new)
rep('function labGrid(){const lgLive=new Set(TD_SLOTS);\n  const srcs=Object.keys(J.dvp);\n  $(\'#labgrid\').innerHTML=`<div class="panel rpane" id="lgFields" hidden></div><div class="controls">\n    ${slotChipsHTML(\'lgSlots\',lgLive)}\n    <select id="lgSrc" title="which data set every column reads">${srcs.map(s=>`<option ${s===\'combined\'?\'selected\':\'\'}>${s}</option>`).join(\'\')}</select>\n    \n    <select id="lgInj"><option value="x" selected>hide OUT</option><option value="">incl. OUT</option></select>\n    <input id="lgQ" placeholder="search player..." size="15">\n    <span class="note">the Matchup Lab dealt four ways. Every number is <b>what this week\'s opponent allows per game to that slot</b>, shaded by where that sits among the ${NT} defenses — green = allows the most = the best matchup, red = the least. The small number beside each figure is its rank of ${NT} (1 = allows the most) &middot; <b>RZ</b> = his red-zone share, <b>L5</b> = his last five vs his season, <b>SCORE</b> = matchup + red zone at fitted weights (click it), <b style="color:#e8b100">$</b> = a contract incentive still in play &middot; each column sorts on its own &middot; click a name for his card</span>\n  </div>\n  <div class="lgrid">${TPOS.map(p=>`<section class="lgcol"><h3>${posIcon(p,12)} ${p} <span class="f" id="lgN${p}"></span></h3><div id="lgB${p}"></div></section>`).join(\'\')}</div>`;\n  const sort={};TPOS.forEach(p=>sort[p]={k:\'psi\',a:true});\n  function col(p){\n    const src=$(\'#lgSrc\').value,st=sort[p];\n    const R=tRows(p,src,{slots:lgLive.size?lgLive:null,hin:$(\'#lgInj\').value,q:$(\'#lgQ\').value});\n    const lgSV=(a,k,asc)=>k===\'rz\'||k===\'l5\'||k===\'sc\'?(v=>v==null?(asc?1e9:-1e9):v)(psVal(a.u,k)):tSortVal(a,k,asc);\n    R.sort((a,b)=>{const x=lgSV(a,st.k,st.a),y=lgSV(b,st.k,st.a);return (x<y?-1:x>y?1:0)*(st.a?1:-1)});\n    const heads=LABDEF[p].heads,sample=LABDEF[p].stats(tKey(p));\n    $(\'#lgN\'+p).textContent=R.length+(R.length===1?\' player\':\' players\');\n    const th=(k,l,tip,cls)=>`<th class="${cls||\'\'}" data-k="${k}" title="${esc(tip||\'\')}">${l}${st.k===k?(st.a?\' ▲\':\' ▼\'):\'\'}</th>`;\n    const wfix=[34,34,38,56];/* v72: fixed pixel columns; the stat columns share what is left */\n    $(\'#lgB\'+p).innerHTML=`<table class="lgt"><colgroup><col class="cnm"><col class="cop">${\n      Array.from({length:heads.length},()=>`<col>`).join(\'\')}${wfix.map((w,i)=>`<col class="cf${i}" style="width:${w}px">`).join(\'\')}</colgroup><thead>\n      <tr class="grp"><th class="g0" colspan="2">player</th>\n        <th class="op" colspan="${heads.length}">allows / game · rank of ${NT}</th>\n        <th class="md" colspan="4" title="Ψ = the matchup in one number · then his own: red-zone share, last-5 trend and the fitted score">matchup · him</th></tr>\n      <tr class="hd">\n      ${th(\'player\',\'Player\')}${th(\'opp\',\'Opp\',"this week\'s opponent")}\n      ${heads.map((h,i)=>th(\'r\'+i,h.split(\'*\').join(\'\'),sample[i]+\' allowed per game to this slot · the pill is its rank of \'+NT,\'op\'+(i===0?\' gs\':\'\'))).join(\'\')}\n      ${th(\'psi\',\'Ψ\',"mean of the opponent\'s ranks across this slot\'s stats · 1 = softest",\'md gs\')}${th(\'rz\',\'RZ\',"his share of his team\'s red-zone targets + carries over his last four games, in % · shaded within his position",\'md\')}${th(\'l5\',\'L5\',\'his PPR over his last five games vs his season average, in % · ▲ up, ▼ down · shown, not weighed (form did not carry over)\',\'md\')}${th(\'sc\',\'SCORE\',\'0–100 within his position: matchup + red-zone share at fitted weights, plus a small bump for a contract incentive in play · click a score for the breakdown\',\'md gs\')}</tr></thead><tbody>\n      ${R.map(x=>`<tr><td class="plink" data-p="${esc(x.u.player)}">${esc(pshort(x.u.player))}${x.u.inj===\'0\'?\' <span class="inj0">Q</span>\':x.u.inj===\'-1\'?\' <span class="injm1">OUT</span>\':\'\'}${psChip(x.u)}</td>\n        <td>${oppcell(x.oppRaw)}</td>\n        ${x.stats.map((c,i)=>tCell(x.raws[i],x.ranks[i],c).replace(\'class="op"\',\'class="op\'+(i===0?\' gs\':\'\')+\'"\')).join(\'\')}\n        ${tPsi(x.psi).replace(\'class="md"\',\'class="md gs"\')}${psCells(x.u)}</tr>`).join(\'\')\n        ||`<tr><td colspan="${heads.length+6}" class="dim">nothing matches</td></tr>`}</tbody></table>`;\n    $(\'#lgB\'+p).querySelectorAll(\'th[data-k]\').forEach(h=>h.onclick=()=>{\n      if(st.k===h.dataset.k)st.a=!st.a;else{st.k=h.dataset.k;st.a=(h.dataset.k===\'psi\'||(h.dataset.k[0]===\'r\'&&h.dataset.k!==\'rz\')||h.dataset.k===\'player\'||h.dataset.k===\'team\'||h.dataset.k===\'opp\')}col(p)});\n    tWire($(\'#lgB\'+p));\n  }\n  const all=()=>{TPOS.forEach(col);const f=$(\'#lgFields\');if(f)rolePane(f,\'prop\')};\n  [\'lgSrc\',\'lgInj\'].forEach(i=>$(\'#\'+i).onchange=all);slotChipsWire(\'lgSlots\',lgLive,all);$(\'#lgQ\').oninput=all;all();\n  RR.push(all);\n}\n', '/* v73 */function lgFit(box){const t=box&&box.querySelector(\'table.lgt\');if(!t)return;t.classList.remove(\'nosub\');if([...t.querySelectorAll(\'td.op\')].some(c=>c.scrollWidth>c.clientWidth+1))t.classList.add(\'nosub\')}\naddEventListener(\'resize\',()=>{clearTimeout(lgFit.t);lgFit.t=setTimeout(()=>document.querySelectorAll(\'#labgrid [id^=lgB]\').forEach(lgFit),150)});\nfunction labGrid(){const lgLive=new Set(TD_SLOTS);\n  const srcs=Object.keys(J.dvp);\n  $(\'#labgrid\').innerHTML=`<div class="panel rpane" id="lgFields" hidden></div><div class="controls">\n    ${slotChipsHTML(\'lgSlots\',lgLive)}\n    <select id="lgSrc" title="which data set every column reads">${srcs.map(s=>`<option ${s===\'combined\'?\'selected\':\'\'}>${s}</option>`).join(\'\')}</select>\n    \n    <select id="lgInj"><option value="x" selected>hide OUT</option><option value="">incl. OUT</option></select>\n    <input id="lgQ" placeholder="search player..." size="15">\n    <span class="note">the Matchup Lab dealt four ways. Every number is <b>what this week\'s opponent allows per game to that slot</b>, shaded by where that sits among the ${NT} defenses — green = allows the most = the best matchup, red = the least. The small number beside each figure is its rank of ${NT} (1 = allows the most) &middot; each column sorts on its own &middot; click a name for his card</span>\n  </div>\n  <div class="lgrid">${TPOS.map(p=>`<section class="lgcol"><h3>${posIcon(p,12)} ${p} <span class="f" id="lgN${p}"></span></h3><div id="lgB${p}"></div></section>`).join(\'\')}</div>`;\n  const sort={};TPOS.forEach(p=>sort[p]={k:\'psi\',a:true});\n  function col(p){\n    const src=$(\'#lgSrc\').value,st=sort[p];\n    const R=tRows(p,src,{slots:lgLive.size?lgLive:null,hin:$(\'#lgInj\').value,q:$(\'#lgQ\').value});\n    R.sort((a,b)=>{const x=tSortVal(a,st.k,st.a),y=tSortVal(b,st.k,st.a);return (x<y?-1:x>y?1:0)*(st.a?1:-1)});\n    const heads=LABDEF[p].heads,sample=LABDEF[p].stats(tKey(p));\n    $(\'#lgN\'+p).textContent=R.length+(R.length===1?\' player\':\' players\');\n    const th=(k,l,tip,cls)=>`<th class="${cls||\'\'}" data-k="${k}" title="${esc(tip||\'\')}">${l}${st.k===k?(st.a?\' ▲\':\' ▼\'):\'\'}</th>`;\n    const nstat=heads.length+1, wname=Math.max(25,45-nstat*3), wopp=15, wnum=((100-wname-wopp)/nstat).toFixed(2);\n    $(\'#lgB\'+p).innerHTML=`<table class="lgt"><colgroup><col style="width:${wname}%"><col style="width:${wopp}%">${\n      Array.from({length:nstat},()=>`<col style="width:${wnum}%">`).join(\'\')}</colgroup><thead>\n      <tr class="grp"><th class="g0" colspan="2">player</th>\n        <th class="op" colspan="${heads.length}">allows / game · rank of ${NT}</th>\n        <th class="md">model</th></tr>\n      <tr class="hd">\n      ${th(\'player\',\'Player\')}${th(\'opp\',\'Opp\',"this week\'s opponent")}\n      ${heads.map((h,i)=>th(\'r\'+i,h.split(\'*\').join(\'\'),sample[i]+\' allowed per game to this slot · the pill is its rank of \'+NT,\'op\'+(i===0?\' gs\':\'\'))).join(\'\')}\n      ${th(\'psi\',\'Ψ\',"mean of the opponent\'s ranks across this slot\'s stats · 1 = softest",\'md gs\')}</tr></thead><tbody>\n      ${R.map(x=>`<tr><td class="plink" data-p="${esc(x.u.player)}">${esc(pshort(x.u.player))}${x.u.inj===\'0\'?\' <span class="inj0">Q</span>\':x.u.inj===\'-1\'?\' <span class="injm1">OUT</span>\':\'\'}</td>\n        <td>${oppcell(x.oppRaw)}</td>\n        ${x.stats.map((c,i)=>tCell(x.raws[i],x.ranks[i],c).replace(\'class="op"\',\'class="op\'+(i===0?\' gs\':\'\')+\'"\')).join(\'\')}\n        ${tPsi(x.psi).replace(\'class="md"\',\'class="md gs"\')}</tr>`).join(\'\')\n        ||`<tr><td colspan="${heads.length+3}" class="dim">nothing matches</td></tr>`}</tbody></table>`;\n    $(\'#lgB\'+p).querySelectorAll(\'th[data-k]\').forEach(h=>h.onclick=()=>{\n      if(st.k===h.dataset.k)st.a=!st.a;else{st.k=h.dataset.k;st.a=(h.dataset.k===\'psi\'||h.dataset.k[0]===\'r\'||h.dataset.k===\'player\'||h.dataset.k===\'team\'||h.dataset.k===\'opp\')}col(p)});\n    tWire($(\'#lgB\'+p));lgFit($(\'#lgB\'+p));\n  }\n  const all=()=>{TPOS.forEach(col);const f=$(\'#lgFields\');if(f)rolePane(f,\'prop\')};\n  [\'lgSrc\',\'lgInj\'].forEach(i=>$(\'#\'+i).onchange=all);slotChipsWire(\'lgSlots\',lgLive,all);$(\'#lgQ\').oninput=all;all();\n  RR.push(all);\n}\n')
# every v72 layout rule goes (Player Grid fit + Category Grid fit); it was the last block before </style>
i = s.index("/* v72 */#labgrid .lgrid{"); j = s.index("</style>", i)
s = s[:i] + "/* v73 */table.lgt.nosub sub.rks{display:none}#labgrid table.lgt td.op{padding-left:3px;padding-right:3px}#labgrid sub.rks{margin-left:1px}\n" + s[j:]
rep("const W=p==='ALL'?[0,28,60,46,40,40,92]:[0,-1,60,46,40,40,92];/* v72: pixels · 0 = the name takes what is left · -1 = no such column */",
    "const W=p==='ALL'?[26,5,19,8,11,8,23]:[31,0,20,8,11,8,22];")
rep("""<colgroup>${W.map((w,i)=>w<0?'':w?`<col class="wc${i}" style="width:${w}px">`:'<col>').join('')}</colgroup>""",
    """<colgroup>${W.map(w=>w?`<col style="width:${w}%">`:'').join('')}</colgroup>""")
rep("""    <span class="mini livestamp"></span>
""", "")
open(P, 'w', encoding='utf-8').write(s); print('v73 applied')
